--- 语言设置界面
function SettingDialog:OpenLanguagePanel()
    if not isNull(self.LanguagePanel) then
        ---首次打开其他设置时设置事件
        if self.isLanguageFirstOpen then
            self.isLanguageFirstOpen = false
            self:InitLanguagePanel()
        end
        self:RefreshLanguagePanel()
    else
        printError("SettingDialog--OpenLanguagePanel--空面板，LanguagePanel")
    end
end

--- 初次打开语言设置界面
function SettingDialog:InitLanguagePanel()
    self:InitLanguageBtns()
    self:InitVoiceBtns()
    self:InitVoicePackBtns()
end

function SettingDialog:InitLanguageBtns()
    -- local AppEngine = CS.Engine.Lib.AppEngine
    -- local languages =  AppEngine.GetConfig("Engine.I18N", "Languages")
    
    local languages = CfUtils.GetConfigLang()
    self.languageBtns = {}
    local curLanguage = CS.Engine.Lib.I18NManager.Instance.CurrentLanguage
    for i, language in ipairs(languages) do
        local btnLanguage = CS.UnityEngine.GameObject.Instantiate(self.RT_LanguageBtn.gameObject, self.RT_LanguageBtnsRoot, false)
        table.insert(self.languageBtns, {btn = btnLanguage, tag = language})
        -- 设置按钮文本
        self:SetLanguageBtnText(btnLanguage, self:GetLanguageName(language))
        -- 设置按钮的选中状态
        if language == curLanguage then
            self:SetLanguageBtnSelected(btnLanguage, true)
            self.curSelectLanguageBtn = btnLanguage
        else
            self:SetLanguageBtnSelected(btnLanguage, false)
        end
        -- 设置按钮的点击回调
        self:SetLanguageBtnEvent(btnLanguage, Bind(self, function()
            CfUtils.StartCoroutineWithBlocker(function()
                if not isNull(self.curSelectLanguageBtn) then
                    self:SetLanguageBtnSelected(self.curSelectLanguageBtn, false)
                    self.curSelectLanguageBtn = nil
                end
                if not isNull(btnLanguage) then
                    self:SetLanguageBtnSelected(btnLanguage, true)
                    self.curSelectLanguageBtn = btnLanguage
                end
                ---@type ActivityMournMgr
                local ActivityMournMgr = import('Game.Activity.Mourn.ActivityMournMgr')
                ActivityMournMgr:GetInstance():OnDestroy()
                print("[设置] 语言切换", language)
                local SDKService = import("Game.Entry.SDKService")
                SDKService:GetInstance():SetLang(language)
                SDKService:GetInstance().thirdSDK["PayUtils"] = nil 
                CS.Engine.Lib.I18NManager.Instance.CurrentLanguage = language
                CS.Engine.Modules.LuaModule.Instance:ClearAllCache()
                SettingModule.AllSettingsReload()
                -- local CoYield = CoYield
                SettingMgr:GetInstance():ReloadSettings()
                ---@type PlayerComponent
                local playerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
                local SDKService = import("Game.Entry.SDKService")
                SDKService:GetInstance():LoadProducts(playerComponent.playerDojo.channelProductIds)
                ---强刷新一次导航条信息
                self.controller:FreshNavigator()
                KCookie.Set("SettingOpenType", 4)
                self:InitComponent()
                coroutine.yield(UIModule.Clear())
                Events.Broadcast(Constants.EventNames.GAME_SWITCH_LANGUAGE, {lang = language})
                GameUtils.Toast(localize("切换成功"))
                
                --- 刷新主界面大活动语言
                ---@type ActivityMgr
                local ActivityMgr = import('Game.Activity.ActivityMgr'):GetInstance()
                ActivityMgr:UpdateActivityHomeData()
                SDKService:GetInstance():UpdateThZoneByEnLang()
                local UIModule = CS.Engine.UI.UIModule
                -- UIModule.CloseDialog(self.controller)
                local cs_coroutine = require 'XLua.cs_coroutine'
                cs_coroutine.yield_return(UIModule.OpenDialog({ id = Constants.UITypeIds.UISettingDialog, parameters = {openType = 4} } ,  { { id = Constants.UITypeIds.UIHomeView } }))
                UIModule.CloseDialog(self.controller)
            end)
        end))
        KTool.SetActive(btnLanguage, true)
    end
end

function SettingDialog:InitVoiceBtns()
    if SettingVoiceMgr == nil then
        SettingVoiceMgr = import("Game.UI.Setting.SettingVoiceMgr")
        SettingVoiceMgr:Init()
        -- 请求更新状态
    end
    local LB_Voice = GetLuaBehaviour(self.RT_VoiceBtnsRoot.gameObject, "Game.UI.Setting.SettingVoiceBtnGroup")
    LB_Voice.Env:InitBtns(self.RT_VoiceBtn, self.RT_VoiceBtnsRoot)
end

function SettingDialog:InitVoicePackBtns()
    local social = AppService:GetInstance():GetSocialLine()
    local batchSyncer = social.batchSyncer
    local needShow = isNotNull(batchSyncer)
    if not needShow then return end

    KTool.SetActive(self.RT_VoicePackBtnGroupRoot, true)
    local LB_VoicePack = GetLuaBehaviour(self.RT_VoicePackBtnGroupRoot.gameObject, "Game.UI.Setting.SettingVoicePackBtnGroup")
    LB_VoicePack.Env:Refresh()
end

--- 刷新语言设置界面
function SettingDialog:RefreshLanguagePanel()
    -- 刷新语言按钮的文字
    for i, btnInfo in ipairs(self.languageBtns) do
        self:SetLanguageBtnText(btnInfo.btn, self:GetLanguageName(btnInfo.tag))
    end
    -- 刷新语音按钮的文字
    local LB_Voice = GetLuaBehaviour(self.RT_VoiceBtnsRoot.gameObject, "Game.UI.Setting.SettingVoiceBtnGroup")
    LB_Voice.Env:RefreshBtns()
    -- 刷新语音包按钮的文字
    local LB_VoicePack = GetLuaBehaviour(self.RT_VoicePackBtnGroupRoot.gameObject, "Game.UI.Setting.SettingVoicePackBtnGroup")
    LB_VoicePack.Env:Refresh()
end

--- 设置语言按钮的文字
---@param btn any
---@param text any
function SettingDialog:SetLanguageBtnText(btn, text)
    local Txt_Desc = btn.transform:Find("Text"):GetComponent(typeof(CS.UnityEngine.UI.Text))
    if not isNull(Txt_Desc) then
        Txt_Desc.text = text
    end
end

--- 设置语言按钮的选中状态
---@param btn any
---@param state any
function SettingDialog:SetLanguageBtnSelected(btn, state)
    local RT_Select = btn.transform:Find("Select")
    if not isNull(RT_Select) then
        KTool.SetActive(RT_Select, state)
    end
end

--- 设置语言按钮的回调事件
---@param btn any
---@param callback any
function SettingDialog:SetLanguageBtnEvent(btn, callback)
    local RT_ClickArea = btn.transform:Find("area")
    if isNull(RT_ClickArea) then return end
    UIEventProxy.Create(RT_ClickArea.gameObject).onPointerClick = callback
end

function SettingDialog:GetLanguageName(languageTag)
    local name = ""
    if languageTag == "zh_CN" then
        name = localize("简体中文")
    elseif languageTag == "zh_TW" then
        name = localize("繁体中文")
    elseif languageTag == "en_US" or languageTag == "en_UK" then
        name = localize("英文")
    elseif languageTag == "ja_JP" then
        name = localize("日文")
    elseif languageTag == "ko_KR" then
        name = localize("韩文")
    elseif languageTag == "th_TH" then
        name = localize("泰文")
    end
    return name
end

function SettingDialog:OpenPushPanel()
    if not isNull(self.PushPanel) then
        self:RefreshPushPanel()
    end
end

function SettingDialog:RefreshPushPanel()
    local lb = GetLuaBehaviour(self.PushPanel.gameObject, "Game.UI.Setting.SettingPushPanel")
    lb.Env:RefreshPanel()
end

