    local lb = GetLuaBehaviour(self.PushPanel.gameObject, "Game.UI.Setting.SettingPushPanel")
    return lb.Env:GetPushBtnsChangedState()
end

function SettingDialog:IsPushMainBtnStateChanged()
    local lb = GetLuaBehaviour(self.PushPanel.gameObject, "Game.UI.Setting.SettingPushPanel")
    return lb.Env:IsMainBtnStateChanged()
end

---打开其他设置面板，目前里面只有一个异形屏适配
function SettingDialog:OpenOtherPanel()
    if not isNull(self.OtherPanel) then
        ---首次打开其他设置时设置事件
        if self.isOtherFirstOpen then
            self.isOtherFirstOpen = false
            self:InitOtherPanel()
        end
        self:RefreshOtherPanel()

        -- local loopListView = self.OtherPanelLoopListView.gameObject:GetComponent(typeof(CS.SuperScrollView.LoopListView2))
        -- print(loopListView)
        -- loopListView.ContainerTrans.anchoredPosition = Vector2(0, 930)

        -- 刷新otherPanel的layout
        CoStop(self.co_otherPanelLayout)
        self.co_otherPanelLayout = CoStart(function()
            CoYield()
            local y1 = self.OtherPanelItemCell1.sizeDelta.y
            local y2 = self.OtherPanelItemCell2.sizeDelta.y
            local y3 = self.OtherPanelItemCell3.sizeDelta.y
    
            self.OtherPanelItemCell2.anchoredPosition = Vector2(0, -y1)
            self.OtherPanelItemCell3.anchoredPosition = Vector2(0, -y1-y2)
    
            self.OtherPanelScrollContent:SetSizeWithCurrentAnchors(CS.UnityEngine.RectTransform.Axis.Vertical, y1+y2+y3)

            self.co_otherPanelLayout = nil
        end)
        
    else
        printError("SettingDialog--OpenOtherPanel--空面板，OtherPanel")
    end
end

---首次打开其他设置时设置事件
function SettingDialog:InitOtherPanel()

    SetButtonAction(self.BtnAdaptive, function ()
        PlayerPrefsUtility.SetEncryptedFloat("customAdaptiveUISetting",DEFAULT_ADAPTIVE_SLIDER_VALUE)
        self:RefreshOtherPanel()
    end)
