function SettingDialog:HandleBindMail()
    ---@type SDKService
    local sdkService =  import('Game.Entry.SDKService'):GetInstance()
    if GameUtils.IsUnlockedBySystemTogId(Constants.SystemToggleIds.Id277)
    and (sdkService:IsForeignSDK() or KTool.UNITY_EDITOR()) then
        CfUtils.SetActive(self.BindMail.transform.parent, true)
        local userComp = GameUtils.GetEntityCompByType(ECSComponentType.Constants.UserComponent)
        local mail = userComp.userInfo.email
        if not string.isEmpty(mail) then
            CfUtils.SetActive(self.BindMail:Find("TxtNumber"), true)
            CfUtils.FillText(self.BindMail:Find("TxtNumber"), mail)
            CfUtils.FillText(self.BindMail:Find("TxtBind"), localize("更换邮箱"))
            CfUtils.SetActive(self.BindMail:Find("HarvestAnim"), false)
        else
            -- 基础参数表:
            --local goodsId = CfUtils.GetCfVo(AutoIds.IdSetting10, "BaseArgVo", 30).num
            --local goodsNum = CfUtils.GetCfVo(AutoIds.IdSetting10, "BaseArgVo", 31).num
            --local goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(goodsId)
            --CfUtils.FillImage(self.BindMail:Find("HarvestAnim/ImgGem/ImgGoodIcon"), goodsVo.photoPath)
            --CfUtils.FillText(self.BindMail:Find("HarvestAnim/ImgGem/TxtNum"), goodsNum)
            CfUtils.SetActive(self.BindMail:Find("TxtNumber"), false)
            CfUtils.FillText(self.BindMail:Find("TxtBind"), localize("绑定邮箱"))
            CfUtils.SetActive(self.BindMail:Find("HarvestAnim"), false)

        end
        SetButtonAction(self.BindMail, function ()
            UIModule.OpenDialog({ id = Constants.UITypeIds.SettingBindEmailPopup, parameters = {cb = function(newEmail)
                CfUtils.SetActive(self.BindMail:Find("TxtNumber"), true)
                CfUtils.FillText(self.BindMail:Find("TxtNumber"), newEmail)
                CfUtils.FillText(self.BindMail:Find("TxtBind"), localize("更换邮箱"))
                CfUtils.SetActive(self.BindMail:Find("HarvestAnim"), false)
            end}})
        end)
    else
        CfUtils.SetActive(self.BindMail.transform.parent, false)
    end
end

function SettingDialog:IsShowCDKExchange()
    local AppEngine = CS.Engine.Lib.AppEngine
    local AppBundleVersion = AppEngine.GetAppBundleVersion()
    local isPreview = IS_REVIEW
    local isImage = AppBundleVersion.Server == "image"
    local isShow = (not isPreview) and (not isImage)
    return isShow
end

