---找到当前带toggle组件的transform
---@param typeIndex number Music = 0, Effect = 1
---@param value number On = 0, Off = 1
function SettingDialog:GetSoundSwitchToggleNode(typeIndex,value)
    if typeIndex == SoundDefaultConfig.Music.Id then
        return self.SoundMusicNode.transform:Find("SettingSwitchNode")
    elseif typeIndex == SoundDefaultConfig.Effect.Id then
        return self.SoundEffectNode.transform:Find("SettingSwitchNode")
    elseif typeIndex == SoundDefaultConfig.Volume.Id then
        return self.SoundVoiceNode.transform:Find("SettingSwitchNode")
    else
        printError("SettingDialog--GetSoundSwitchToggleNode--参数错误，typeIndex："..typeIndex.."value:"..value)
    end
end

function SettingDialog:GetSoundSwitchBg(typeIndex)
    if typeIndex == SoundDefaultConfig.Music.Id then
        return self.SoundMusicNode.transform:Find("SwitchGroup/SelectedBg")
    elseif typeIndex == SoundDefaultConfig.Effect.Id then
        return self.SoundEffectNode.transform:Find("SwitchGroup/SelectedBg")
    elseif typeIndex == SoundDefaultConfig.Volume.Id then
        return self.SoundVoiceNode.transform:Find("SwitchGroup/SelectedBg")
    else
        printError("SettingDialog--GetSoundSwitchToggleNode--参数错误，typeIndex："..typeIndex)
    end
end

---找到SliderGroup下的Slider或者右侧显示Size的transform
---@param typeIndex number Music = 0, Effect = 1
---@param typeIndex string 可选参数"Slider", "Size"
function SettingDialog:GetSoundSliderNode(typeIndex,type)
    if typeIndex == SoundDefaultConfig.Music.Id then
        return self.SoundMusicNode.transform:Find("SliderGroup/"..type)
    elseif typeIndex == SoundDefaultConfig.Effect.Id then
        return self.SoundEffectNode.transform:Find("SliderGroup/"..type)
    elseif typeIndex == SoundDefaultConfig.Volume.Id then
        return self.SoundVoiceNode.transform:Find("SliderGroup/"..type)
    else
        printError("SettingDialog--GetSoundSliderNode--参数错误，typeIndex："..typeIndex.."type:"..type)
    end
end

---刷新声音设置UI
function SettingDialog:RefreshSoundPanel()
    local customSoundSettingsData = self:GetCustomSoundSettings()
    --local switchCount = 2--开关类型Toggle数量
    for k, v in pairs(customSoundSettingsData) do
        if v.Id == 0 then
            local scr = CfUtils.GetLuaScr(self:GetSoundSwitchToggleNode(v.Id), "Game.UI.Setting.SettingSwitchNode")
            scr:FreshSwitchStatus(not self.isOpenMusic)
        elseif v.Id == 1 then
            local scr = CfUtils.GetLuaScr(self:GetSoundSwitchToggleNode(v.Id), "Game.UI.Setting.SettingSwitchNode")
            scr:FreshSwitchStatus(not self.isOpenEffect)
        elseif v.Id == 2 then
            local scr = CfUtils.GetLuaScr(self:GetSoundSwitchToggleNode(v.Id), "Game.UI.Setting.SettingSwitchNode")
            scr:FreshSwitchStatus(not self.isOpenVolume)
        end
        --local bg = self:GetSoundSwitchBg(v.Id)
        --local path = v.Switch == 0 and "UIAtlas/Setting/set_btn_switch_pressed.png" or "UIAtlas/Setting/set_btn_switch_default.png"
        --CfUtils.FillImage(bg,path)
        --for j = 1, switchCount do
        --    KTool.SetActive(self:GetSoundSwitchToggleNode(v.Id,j-1):Find("Default"), v.Switch ~= j - 1)
        --end
        self:GetSoundSliderNode(v.Id,"Slider"):GetComponent(typeof(Slider)).interactable = v.Switch == 0 and true or false
        self:GetSoundSliderNode(v.Id,"Slider"):GetComponent(typeof(Slider)).value = v.Slider
        local node = self:GetSoundSliderNode(v.Id,"Size")
        CfUtils.FillText(node, math.floor(v.Slider * 100))
    end
end

---@param typeIndex number Music = 0, Effect = 1
---@param value number On = 0, Off = 1
function SettingDialog:SettingSoundSwitch(typeIndex,value)
    local customSoundSettingsData = self:GetCustomSoundSettings()
    if typeIndex == SoundDefaultConfig.Music.Id then
        CriWareUtils.SetVolume(Constants.CriWareCategory.BGM, value == 0 and customSoundSettingsData.Music.Slider or 0)
        self:SettingSoundPlayerPrefsByType("Music","Switch",value)
    elseif typeIndex == SoundDefaultConfig.Effect.Id then
        CriWareUtils.SetVolume(Constants.CriWareCategory.SE, value == 0 and customSoundSettingsData.Effect.Slider or 0)
        self:SettingSoundPlayerPrefsByType("Effect","Switch",value)
    elseif typeIndex == SoundDefaultConfig.Volume.Id then
        CriWareUtils.SetVolume(Constants.CriWareCategory.VOICE, value == 0 and customSoundSettingsData.Volume.Slider or 0)
        self:SettingSoundPlayerPrefsByType("Volume","Switch",value)
    else
        printError("SettingDialog--SettingSoundSwitch--参数错误，typeIndex："..typeIndex.."value:"..value)
    end
end

---@param typeIndex number Music = 0, Effect = 1,Volume = 2
---@param value number slider.value
function SettingDialog:SettingSoundSlider(typeIndex,value)
    local customSoundSettingsData = self:GetCustomSoundSettings()
    if typeIndex == SoundDefaultConfig.Music.Id then
        if customSoundSettingsData.Music.Switch == 1 then
            CriWareUtils.SetVolume(Constants.CriWareCategory.BGM, 0)
        else
            CriWareUtils.SetVolume(Constants.CriWareCategory.BGM, value)
        end
        self:SettingSoundPlayerPrefsByType("Music","Slider",value)
    elseif typeIndex == SoundDefaultConfig.Effect.Id then
        if customSoundSettingsData.Effect.Switch == 1 then
            CriWareUtils.SetVolume(Constants.CriWareCategory.SE, 0)
        else
            CriWareUtils.SetVolume(Constants.CriWareCategory.SE, value)
        end
        self:SettingSoundPlayerPrefsByType("Effect","Slider",value)
    elseif typeIndex == SoundDefaultConfig.Volume.Id then
        if customSoundSettingsData.Volume.Switch == 1 then
            CriWareUtils.SetVolume(Constants.CriWareCategory.VOICE, 0)
        else
            CriWareUtils.SetVolume(Constants.CriWareCategory.VOICE, value)
        end
        self:SettingSoundPlayerPrefsByType("Volume","Slider",value)
    else
        printError("SettingDialog--SettingSoundSlider--参数错误，typeIndex："..typeIndex.."value:"..value)
    end
end

