function SettingDialog:SetGraphicAllSelectStatus(index, status)
    local node = self.QualityToggleGroup:Find("QualityToggleGo"..index)
    if node then
        local checked = self:GetQualityToggleCheckedGo(node, index)
        KTool.SetActive(checked, status)
    end
end

function SettingDialog:GetQualityToggleCheckedGo(parent, index)
    if isNull(parent) then
        return
    end
    index = checkInt(index)
    local checked = parent.transform:Find(index == 1 and "Checked1" or "Checked")
    return checked
end

function SettingDialog:RefreshGraphicPanel()
    -- 刷新顶部的级别按钮的文字
    self.globalGraphicConfig = self:GetGraphicQualityVoList()
    for i = 1, #self.globalGraphicConfig do
        local QualityToggleGo = self.QualityToggleGroup:Find("QualityToggleGo"..i)
        if QualityToggleGo then
            local label = QualityToggleGo.transform:Find("Label")
            CfUtils.FillText(label, self.globalGraphicConfig[i].name)
        end
    end
    -- 刷新下面的配置选项的文字
    for k, v in ipairs(GraphicSettingOptionData) do
        if k < GRAPHIC_OPTION_INDEX.SHADOW then --等级选项
            local OptionToggleGo = self.OptionList:Find("OptionToggleGo"..k)
            local Text = OptionToggleGo.transform:Find("Text")
            CfUtils.FillText(Text, v.name())
            for i, b in ipairs(v.level) do
                self[k..b.id]:FreshBaseUI({desc = b.desc()})
            end
            KTool.SetActive(OptionToggleGo, true)
        else --开关
            local SwitchGo
            SwitchGo = self.BottomNode:Find("SwitchGo"..k)
            local text = SwitchGo.transform:Find("Text")
            CfUtils.FillText(text, v.name())
        end
    end
end

---首次打开界面设置时设置事件
