                    if not self.isClickGraphicQuality then
                        self:SetGraphicAllSelectStatus(self.selectGraphicAllIndex, false)
                        KTool.SetActive(self.QualityToggleCustom.transform:Find("Checked"), true)
                        self:SettingQualityLevel(CUSTOM_GRAPHIC_LEVEL)
                    end
                end)

                --local toggle = LevelToggleGo.transform:GetComponent(typeof(Toggle))
                --SetToggleValueChanged(toggle, function(value)
                --    if k ~= GRAPHIC_OPTION_INDEX.FPS then
                --        KTool.SetActive(Selected , value)
                --    else
                --        if b.id == 60 then
                --            if value then
                --                GameUtils.SecondConfirm(
                --                        localize("确定开启吗？开启高帧率模式可能会加快手机好点、加热，性能较低手机可能会出现卡顿"),
                --                        function()
                --                            KTool.SetActive(Selected , value)
                --                        end
                --                )
                --            end
                --        else
                --            KTool.SetActive(Selected , value)
                --        end
                --    end
                --    if value then
                --        if k == GRAPHIC_OPTION_INDEX.GRAPHIC then
                --            self:SettingGraphicLevel(b.id)
                --        elseif k == GRAPHIC_OPTION_INDEX.RESOLUTION then
                --            self:SettingGraphicResolution(b.id)
                --        elseif k == GRAPHIC_OPTION_INDEX.FPS then
                --            self:SettingGraphicFrame(b.id)
                --        elseif k == GRAPHIC_OPTION_INDEX.BLOOM then
                --            self:SettingGraphicGlow(b.id)
                --        end
                --        if not self.isClickGraphicQuality then
                --            self.QualityToggleCustom.isOn = false
                --            self.QualityToggleCustom.isOn = true
                --            self:SettingQualityLevel(CUSTOM_GRAPHIC_LEVEL)
                --        end
                --    end
                --end)
                KTool.SetActive(LevelToggleGo, true)
                if self.customGraphicSettingsData.level == CUSTOM_GRAPHIC_LEVEL then --自定义设置,非自定义设置由总开关调用
                    if k == GRAPHIC_OPTION_INDEX.GRAPHIC then
                        if b.id == self.customGraphicSettingsData.graphicLevel then
                            self:SettingGraphicLevel(b.id)
                            self:ChangeGraphicSetStatus(k, b)
                        end
                    elseif k == GRAPHIC_OPTION_INDEX.RESOLUTION then
                        if b.id == self.customGraphicSettingsData.resolutionLevel then
                            self:SettingGraphicResolution(b.id)
                            self:ChangeGraphicSetStatus(k, b)
                        end
                    elseif k == GRAPHIC_OPTION_INDEX.FPS then
                        if b.id == self.customGraphicSettingsData.fpsLevel then
                            self:SettingGraphicFrame(b.id)
                            self:ChangeGraphicSetStatus(k, b)
                        end
                    elseif k == GRAPHIC_OPTION_INDEX.BLOOM then
                        if b.id == self.customGraphicSettingsData.bloomLevel then
                            self:SettingGraphicGlow(b.id)
                            self:ChangeGraphicSetStatus(k, b)
                        end
                    elseif k == GRAPHIC_OPTION_INDEX.MATERIAL then
                        if b.id == self.customGraphicSettingsData.lodLevel then
                            self:SettingGraphicMaterial(b.id)
                            self:ChangeGraphicSetStatus(k, b)
                        end
                    end
                    if not self.isClickGraphicQuality then
                        KTool.SetActive(self.QualityToggleCustom.transform:Find("Checked"), true)
                        --self.QualityToggleCustom.isOn = false
                        --self.QualityToggleCustom.isOn = true
                        self:SettingQualityLevel(CUSTOM_GRAPHIC_LEVEL)
                    end
                end
            end
            KTool.SetActive(OptionToggleGo, true)
        else --开关
            local SwitchGo
            SwitchGo = self.BottomNode:Find("SwitchGo"..k)
            if not SwitchGo then
                SwitchGo = CfUtils.InstantiateGo(self.SwitchPrefab, self.BottomNode)
                SwitchGo.name = "SwitchGo"..k
            end
            local text = SwitchGo.transform:Find("Text")
            CfUtils.FillText(text, v.name())
            local switchGroup = SwitchGo.transform:Find("SwitchGroup")
            local maskOn = switchGroup:Find("MaskOn")
            local maskOff = switchGroup:Find("MaskOff")
            local btn = switchGroup:GetComponent(typeof(Button))
            if k == GRAPHIC_OPTION_INDEX.SHADOW then
                self.shadowStatus = self.customGraphicSettingsData.shadowLevel
                KTool.SetActive(maskOn, self.shadowStatus == 0)
                KTool.SetActive(maskOff, self.shadowStatus == 1)
            elseif k == GRAPHIC_OPTION_INDEX.FXAA then
                self.fxaaStatus = self.customGraphicSettingsData.fxaaLevel
                KTool.SetActive(maskOn, self.fxaaStatus == 0)
                KTool.SetActive(maskOff, self.fxaaStatus == 1)
            end
            SetButtonAction(btn, function()
                self:SetGraphicAllSelectStatus(self.selectGraphicAllIndex, false)
                self:GraphicBtnAction(k, true)
            end)
            KTool.SetActive(SwitchGo, true)
            if self.customGraphicSettingsData.level == CUSTOM_GRAPHIC_LEVEL then --自定义设置,非自定义设置由总开关调用
                if k == GRAPHIC_OPTION_INDEX.SHADOW then
                    self.shadowStatus = self.customGraphicSettingsData.shadowLevel
                    self:GraphicBtnAction(k, false, self.shadowStatus)
                elseif k == GRAPHIC_OPTION_INDEX.FXAA then
                    self.fxaaStatus = self.customGraphicSettingsData.fxaaLevel
                    self:GraphicBtnAction(k, false, self.fxaaStatus)
                end

            end
        end
