    ---
    ---设置事件，TopNode中整体调整画质等级
    for i = 1, #self.globalGraphicConfig do
        local QualityToggleGo
        QualityToggleGo = self.QualityToggleGroup:Find("QualityToggleGo"..i)
        if not QualityToggleGo then
            QualityToggleGo = CfUtils.InstantiateGo(self.QualityTogglePrefab, self.QualityToggleGroup)
            QualityToggleGo.name = "QualityToggleGo"..i
        end
        local label = QualityToggleGo.transform:Find("Label")
        local checked = self:GetQualityToggleCheckedGo(QualityToggleGo, i)
        CfUtils.FillText(label, self.globalGraphicConfig[i].name)
        KTool.SetActive(checked, i - 1 == self.customGraphicSettingsData.level)
        self.selectGraphicAllIndex = self.customGraphicSettingsData.level + 1
        SetButtonAction(QualityToggleGo, function ()
            print("-->>QualityToggleGo")
            local func = function()
                KTool.SetActive(self.QualityToggleCustom.transform:Find("Checked"), false)
                local preNode = self.QualityToggleGroup:Find("QualityToggleGo"..self.selectGraphicAllIndex)
                if preNode then
                    local checked = self:GetQualityToggleCheckedGo(preNode, self.selectGraphicAllIndex)
                    KTool.SetActive(checked, false)
                end
                KTool.SetActive(checked, true)
                self.isClickGraphicQuality = true
                self:SettingGraphicAll(self.globalGraphicConfig[i])
                self.selectGraphicAllIndex = i
            end
            if i == #self.globalGraphicConfig then
                self:HighLevelGraphicSetting(function()
                    func()
                end)
            else
                func()
            end
        end)
        self.isClickGraphicQuality = true
        KTool.SetActive(QualityToggleGo, true)
    end
    self:SettingGraphicAll(self.customGraphicSettingsData)
end

function SettingDialog:HighLevelGraphicSetting(confirmCB)
    if Application.platform == RuntimePlatform.WindowsEditor or Application.platform == RuntimePlatform.WindowsPlayer then
        print("HighLevelGraphicSetting--------")
        confirmCB()
    else
        GameUtils.SecondConfirm(
                localize("开启高帧率模式可能会导致手机耗电增加、发热，性能较低手机可能会出现卡顿。"),
                function()
                    confirmCB()
                end
        )
    end
end


---设置成功后的表现
---@param k number GRAPHIC_OPTION_INDEX
---@param b number GraphicSettingOptionData[k].level.id
function SettingDialog:ChangeGraphicSetStatus(k, b)
    if not isNull(self["selected"..k]) then--前面的取消选中
        self[k..self["selected"..k]]:FreshSelectStatus(false)
    end
    self["selected"..k] = b.id
    self[k..b.id]:FreshSelectStatus(true)
end

function SettingDialog:GraphicBtnAction(index, isClick, level)
    local SwitchGo = self.BottomNode:Find("SwitchGo"..index)
    local switchGroup = SwitchGo.transform:Find("SwitchGroup")
    local bg = switchGroup:Find("SelectedBg")
    local path
    local maskOn = switchGroup:Find("MaskOn")
    local maskOff = switchGroup:Find("MaskOff")
    if index == GRAPHIC_OPTION_INDEX.SHADOW then
        if isClick then
            if self.shadowStatus == 0 then --开关的状态
                self.shadowStatus = 1
            else
                self.shadowStatus = 0
            end
        else
            self.shadowStatus = level
        end
        self:SettingGraphicShadow(self.shadowStatus)
        KTool.SetActive(maskOn, self.shadowStatus == 0)
        KTool.SetActive(maskOff, self.shadowStatus == 1)
        path = self.shadowStatus == 0 and "UIAtlas/Setting/set_btn_switch_default.png" or "UIAtlas/Setting/set_btn_switch_pressed.png"
    elseif index == GRAPHIC_OPTION_INDEX.FXAA then
        if isClick then
            if self.fxaaStatus == 0 then --开关的状态
                self.fxaaStatus = 1
            else
                self.fxaaStatus = 0
            end
        else
            self.fxaaStatus = level
        end
        self:SettingGraphicAntialiasing(self.fxaaStatus)
        KTool.SetActive(maskOn, self.fxaaStatus == 0)
        KTool.SetActive(maskOff, self.fxaaStatus == 1)
        path = self.fxaaStatus == 0 and "UIAtlas/Setting/set_btn_switch_default.png" or "UIAtlas/Setting/set_btn_switch_pressed.png"
    end
    CfUtils.FillImage(bg, path)
    if not self.isClickGraphicQuality then
        KTool.SetActive(self.QualityToggleCustom.transform:Find("Checked"), true)
        --self.QualityToggleCustom.isOn = true
        self:SettingQualityLevel(CUSTOM_GRAPHIC_LEVEL)
    end
end

---一键设置流畅、精细、完美、自定义画面质量
---@param configTable table 格式参考配置的GlobalGraphicConfig.Low
function SettingDialog:SettingGraphicAll(configTable)
    self:SettingQualityLevel(configTable.level)
    self[GRAPHIC_OPTION_INDEX.GRAPHIC..configTable.graphicLevel]:ExecuteCb()
    self[GRAPHIC_OPTION_INDEX.RESOLUTION..configTable.resolutionLevel]:ExecuteCb()
    self[GRAPHIC_OPTION_INDEX.FPS..configTable.fpsLevel]:ExecuteCb()
    self[GRAPHIC_OPTION_INDEX.BLOOM..configTable.bloomLevel]:ExecuteCb()
    self[GRAPHIC_OPTION_INDEX.MATERIAL..configTable.lodLevel]:ExecuteCb()
    --self.graphicToggleGroup:Find("LevelToggleGo"..configTable.graphicLevel):GetComponent(typeof(Toggle)).isOn = true
    --self.resolutionToggleGroup:Find("LevelToggleGo"..configTable.resolutionLevel):GetComponent(typeof(Toggle)).isOn = true
    --self.fpsToggleGroup:Find("LevelToggleGo"..configTable.fpsLevel):GetComponent(typeof(Toggle)).isOn = true
    --self.bloomToggleGroup:Find("LevelToggleGo"..configTable.bloomLevel):GetComponent(typeof(Toggle)).isOn = true
    self:GraphicBtnAction(GRAPHIC_OPTION_INDEX.SHADOW, false, configTable.shadowLevel)
    self:GraphicBtnAction(GRAPHIC_OPTION_INDEX.FXAA, false, configTable.fxaaLevel)

    self.isClickGraphicQuality = false
end

function SettingDialog:SettingGraphicLevel(index)
    XGraphicSetup.ApplyGraphic(index)
    self:SettingGraphicPlayerPrefsByOptionType("graphicLevel",index)
end

function SettingDialog:SettingGraphicResolution(index)
    local vo = CfUtils.GetCfVo(AutoIds.IdSetting940, "ResolutionVo", index)
    XGraphicSetup.ApplyResolution(vo)
    self:SettingGraphicPlayerPrefsByOptionType("resolutionLevel",index)
