    self:SettingGraphicPlayerPrefsByOptionType("shadowLevel",index)
end

function SettingDialog:SettingGraphicAntialiasing(index)
    local vo = CfUtils.GetCfVo(AutoIds.IdSetting942, "AntialiasingVo", index)
    XGraphicSetup.ApplyAntialias(vo)
    self:SettingGraphicPlayerPrefsByOptionType("fxaaLevel",index)
end

function SettingDialog:SettingGraphicGlow(index)
