---获取本地存储的界面设置数据
function SettingDialog:GetCustomGraphicSettings()
    local customGraphicSettings = PlayerPrefsUtility.GetEncryptedString(CUSTOM_SETTING_PREFS)
    local data
    if string.isEmpty(customGraphicSettings) then
        data = self.globalGraphicConfig[self.defaultGraphicQuality]
        if Application.platform == CS.UnityEngine.RuntimePlatform.Android then
            --如果是泰国，新用户默认关闭抗锯齿
            data.fxaaLevel = 0
            data.level = CUSTOM_GRAPHIC_LEVEL
        end 
    else
        data = table.deserialize(customGraphicSettings)
    end
    return data
end

---获取本地存储的声音设置数据
function SettingDialog:GetCustomSoundSettings()
    local customSoundSettingsData = PlayerPrefsUtility.GetEncryptedString("customSoundSettings")
    local data
    if string.isEmpty(customSoundSettingsData) then
        data = SoundDefaultConfig
    else
        data = table.deserialize(customSoundSettingsData)
        --@region-----------这个是新加的参数，为了适配已有的缓存做的特殊判断，测试结束后去掉
        if isNull(data.Volume) then
            data["Volume"] = SoundDefaultConfig.Volume
        end
        --@endregion--------
    end
    return data
end

---本地数据存储
---@param sound_type string Music/Effect
---@param option_type string Switch/Slider
---@param index number
function SettingDialog:SettingSoundPlayerPrefsByType(sound_type,option_type,value)
    if table.haskey(SoundDefaultConfig,sound_type) and table.haskey(SoundDefaultConfig[sound_type],option_type) then
        local customSoundSettingsData = self:GetCustomSoundSettings()
        customSoundSettingsData[sound_type][option_type] = value
        PlayerPrefsUtility.SetEncryptedString("customSoundSettings",table.serialize(customSoundSettingsData))
    else
        printError("SettingDialog--SettingSoundPlayerPrefsByType--参数错误，sound_type:"..sound_type.."option_type:"..option_type.."value:"..value.."\n正确格式请见SoundDefaultConfig")
    end
end

---本地数据存储
---@param option_type string
---@param index number
function SettingDialog:SettingGraphicPlayerPrefsByOptionType(option_type,index)
    local customGraphicSettingsData = self:GetCustomGraphicSettings()
    customGraphicSettingsData[option_type] = index
    PlayerPrefsUtility.SetEncryptedString(CUSTOM_SETTING_PREFS,table.serialize(customGraphicSettingsData))
end

---UI的淡入淡出效果
---@param targetGo UnityEngine.Transform 目标物体 需要带有CanvasGroup组件
---@param alphaStart number 起始alpha值
---@param alphaEnd number 结束alpha值
---@param time number 持续时间
function SettingDialog:Fade(targetGo,alphaStart,alphaEnd,time)
    local target = targetGo:GetComponent(typeof(CanvasGroup))
    if target then
        target.alpha = alphaStart
        target:DOFade(alphaEnd, time):SetEase(DOTween.Ease.InOutQuad)
    else
        printError("SettingDialog--Fade--请检查是否带有CanvasGroup组件")
    end
end

function SettingDialog:GetGraphicQualityVoList()
    local settingMgr = SettingMgr:GetInstance()
    local tableFile = settingMgr:Get(AutoIds.IdSetting9)
    local GraphicQualityVo = import('Game.Setting.Vo.GraphicQualityVo')
    local graphicQualityVoList = {}
    for i, row in pairs(tableFile) do
        local vo = GraphicQualityVo.New()
        vo:FillVo(row)
        vo.Delete = nil
        vo.class = nil
        table.insert(graphicQualityVoList, vo)
    end
    return graphicQualityVoList
end

function SettingDialog:FriendSetting()
    local maxLevel = checkNumber(CfUtils.GetCfVo(AutoIds.IdSetting11, "FriendArgVo", 11).num)
    local minLevel = checkNumber(CfUtils.GetCfVo(AutoIds.IdSetting11, "FriendArgVo", 12).num)
    local playerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
    local isOpenAddFriendDojo = checkNumber(playerComponent.playerDojo.isOpenAddFriend) == 1
    local addFriendLevelLimitDojo = playerComponent.playerDojo.addFriendLevelLimit
    local equipmentAutoLockDojo = checkNumber(playerComponent.playerDojo.equipmentAutoLock) == 1
    local change1 = false
    if isNull(self.isOpenAddFriend) then
        change1 = false
    else
        change1 = isOpenAddFriendDojo ~= self.isOpenAddFriend
    end
    local change2 = checkNumber(addFriendLevelLimitDojo) ~= checkNumber(self.FriendInputField.text)
    if checkNumber(self.FriendInputField.text) < minLevel or checkNumber(self.FriendInputField.text) > maxLevel or string.isEmpty(self.FriendInputField.text) then
        change2 = false
    end
    local change3, pushBtnJson = self:GetPushBtnsChangedState()
    local change4 = false
    if isNull(self.equipmentAutoLock) then
        change4 = false
    else
        change4 = equipmentAutoLockDojo ~= self.equipmentAutoLock
    end
    local shouldReq = change1 or change2 or change3 or change4
    if shouldReq then
        local arg1
        if change1 then
            arg1 = self.isOpenAddFriend and 1 or 0
        else
            arg1 = isOpenAddFriendDojo and 1 or 0
        end
        local arg2
        if change2 then
            arg2 = checkNumber(self.FriendInputField.text)
        else
            arg2 = checkNumber(addFriendLevelLimitDojo)
        end
        local arg3 = pushBtnJson
        -----临时的200级限制
        --Mathf.Clamp(arg2, maxLevel)
        --if checkNumber(arg2) > maxLevel then
        --    arg2 = maxLevel
        --end
        local arg4
        if change4 then
            arg4 = self.equipmentAutoLock and 1 or 0
        else
            arg4 = equipmentAutoLockDojo and 1 or 0
        end
        GameUtils.Request(
                Interfaces.PlayerSite,
                {
                    isOpenAddFriend = arg1,
                    addFriendLevelLimit = arg2,
                    pushSettings = arg3,
                    equipmentAutoLock = arg4    
                },
                function(request, response)
                    if checkInt(response.errCode) == 0 then
                        local playerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
                        playerComponent.playerDojo.isOpenAddFriend = arg1
                        playerComponent.playerDojo.addFriendLevelLimit = arg2
                        playerComponent.playerDojo.equipmentAutoLock = arg4
                        print("friendSetSuccess---->>")
                    end
                end
        )

        -- 推送总开关状态变化时，修改推送SDK状态
        local pushMainBtnChanged, newState = self:IsPushMainBtnStateChanged()
        if pushMainBtnChanged then
            ---@type SDKService
            local SDKService = import('Game.Entry.SDKService')
            local sdkService = SDKService:GetInstance()
            ---@type TpnsSdk
            local TpnsSdk =  sdkService:GetThirdSDK("TpnsSdk")
            if isNotNull(TpnsSdk) then
                if newState == 1 then
                    print("[推送] 更新推送SDK状态 open")
                    TpnsSdk:OpenNotice()
                else
                    print("[推送] 更新推送SDK状态 close")
                    TpnsSdk:CloseNotice()
                end
            end
        end
    end
end

function SettingDialog:OnFinalize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        CoStop(self.co_otherPanelLayout)
        self.co_otherPanelLayout = nil
        if self.isLogout == nil then
            self:FriendSetting()
        end
        self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
        self:Delete()
        self = nil --lua层的gc需要
    end))
    return coWait
end





function SettingDialog.Get_CUSTOM_SETTING_PREFS()
    return CUSTOM_SETTING_PREFS
end

function SettingDialog.Get_SettingLODPath()
    return SettingLODPath
end


return SettingDialog